const initial=()=>{try{const stored=localStorage.getItem('spectra-studio.autosave.v1');if(stored)return validateProject(JSON.parse(stored));}catch(e){console.warn('Autosave unavailable',e);}return makeProject();};
let project=initial(),workspace='vfx',selection={kind:'emitter',id:project.emitters[0]?.id||null},playing=false,currentTime=0,playStarted=0,playOffset=0,rafLast=performance.now(),audioCtx=null,audioNode=null,soundPreviewNode=null,history=[],historyIndex=-1,timelineScale=85,timelineDrag=null,waveDirty=true,mixCache=null,storePending=null,frameCounter=0,frameStamp=performance.now();
const preview=new VFXPreview($('stage-canvas'),()=>project);
preview.grid=project.settings.grid!==false;
preview.background=project.settings.background||'studio';
const listFor=kind=>kind==='emitter'?project.emitters:project.sounds;
const getSelected=()=>listFor(selection.kind).find(x=>x.id===selection.id)||null;
const toNumber=(v,min,max)=>clamp(Number(v),min,max);
function notify(message,isError=false){const node=document.createElement('div');node.className='toast'+(isError?' error':'');node.textContent=message;$('toasts').append(node);setTimeout(()=>node.remove(),3500);$('status-message').textContent=message;}
function autosave(){clearTimeout(storePending);storePending=setTimeout(()=>{try{localStorage.setItem('spectra-studio.autosave.v1',JSON.stringify(project));}catch(e){console.warn('Could not save local copy',e);}},500);}
function snap(label){const text=JSON.stringify(project);if(history[historyIndex]?.data===text)return;history=history.slice(0,historyIndex+1);history.push({label,data:text});if(history.length>60)history.shift();historyIndex=history.length-1;autosave();waveDirty=true;updateHistoryButtons();}
function updateHistoryButtons(){document.querySelector('[data-action="undo"]').disabled=historyIndex<=0;document.querySelector('[data-action="redo"]').disabled=historyIndex>=history.length-1;}
function undo(){if(historyIndex<=0)return;historyIndex--;restoreFromHistory();}
function redo(){if(historyIndex>=history.length-1)return;historyIndex++;restoreFromHistory();}
function restoreFromHistory(){const h=history[historyIndex];project=validateProject(JSON.parse(h.data));playing=false;stopAudio();currentTime=0;preview.reset();if(!getSelected())selection={kind:'emitter',id:project.emitters[0]?.id||null};renderAll();notify(h.label);}
function choose(kind,id){selection={kind,id};if(kind==='emitter'&&workspace==='audio')workspace='vfx';if(kind==='sound'&&workspace==='vfx')workspace='audio';renderAll();}
function add(kind,preset){const item=preset==='blank'?(kind==='emitter'?createBlankEmitter():createBlankSound()):(kind==='emitter'?createEmitter(preset):createSound(preset));item.start=clamp(currentTime,0,project.duration-0.1);if(kind==='sound')item.duration=Math.min(item.duration,Math.max(.1,project.duration-item.start));if(kind==='emitter')item.duration=Math.max(.1,project.duration-item.start);listFor(kind).push(item);selection={kind,id:item.id};workspace=workspace==='composer'?'composer':(kind==='emitter'?'vfx':'audio');snap('Add '+item.name);renderAll();if(kind==='emitter')preview.burst(item.id);notify(item.name+' added');}
function duplicate(){const s=getSelected();if(!s)return notify('Select a layer to duplicate',true);const item=structuredClone(s);item.id=uid();item.name=s.name+' Copy';item.start=clamp(s.start+.25,0,project.duration-.1);listFor(selection.kind).push(item);selection={kind:selection.kind,id:item.id};snap('Duplicate '+s.name);renderAll();}
function remove(){const s=getSelected();if(!s)return notify('Select a layer to delete',true);const list=listFor(selection.kind);const index=list.indexOf(s);list.splice(index,1);selection={kind:selection.kind,id:list[Math.max(0,index-1)]?.id||null};snap('Delete '+s.name);renderAll();}
function toggleLayer(kind,id,field){const s=listFor(kind).find(x=>x.id===id);if(!s)return;s[field]=!s[field];snap((field==='solo'?'Solo ':'Toggle ')+s.name);renderAll();}
function moveLayer(direction){const s=getSelected();if(!s)return;const items=listFor(selection.kind),i=items.indexOf(s),j=clamp(i+direction,0,items.length-1);if(i===j)return;items.splice(i,1);items.splice(j,0,s);snap('Reorder '+s.name);renderAll();}
function newProject(){if(!confirm('Create a new blank Spectra project? Your current project can be saved first.'))return;stopAudio();playing=false;preview.reset();project=makeProject();project.emitters=[];project.sounds=[];project.name='Untitled Project';selection={kind:'emitter',id:null};currentTime=0;history=[];historyIndex=-1;snap('New blank project');renderAll();notify('New project created');}
function setWorkspace(w){workspace=w;if(w==='vfx'&&selection.kind!=='emitter')selection={kind:'emitter',id:project.emitters[0]?.id||null};if(w==='audio'&&selection.kind!=='sound')selection={kind:'sound',id:project.sounds[0]?.id||null};renderAll();}
function renderAll(){renderHeader();renderLibrary();renderPresets();renderInspector();renderTimeline();renderStage();updateHistoryButtons();}
function renderHeader(){$('project-name').value=project.name;$('project-duration').value=project.duration;$('project-bpm').value=project.bpm;document.querySelectorAll('[data-workspace]').forEach(b=>b.classList.toggle('active',b.dataset.workspace===workspace));}
function renderLibrary(){const isSound=workspace==='audio',kind=isSound?'sound':'emitter',entries=workspace==='composer'?[...project.emitters.map(item=>({item,kind:'emitter'})),...project.sounds.map(item=>({item,kind:'sound'}))]:listFor(kind).map(item=>({item,kind})),term=$('layer-search').value.trim().toLowerCase();$('layer-title').textContent=isSound?'Sound layers':workspace==='composer'?'All cue layers':'Effect layers';const list=$('layer-list');list.innerHTML=entries.filter(({item})=>item.name.toLowerCase().includes(term)).map(({item:s,kind})=>`<div class="layer ${selection.id===s.id?'selected':''}" data-select="${esc(s.id)}" data-kind="${kind}" role="button" tabindex="0"><span class="layer-symbol" style="color:${kind==='emitter'?esc(s.colorStart):'#b9a2ff'}">${kind==='emitter'?'✦':'♫'}</span><span class="layer-content"><strong>${esc(s.name)}</strong><small>${kind==='emitter'?`${Math.round(s.rate)} /sec · ${Number(s.life).toFixed(1)}s life`:`${Number(s.duration).toFixed(2)}s · ${Math.round(s.freq)} Hz`}</small></span><button class="mute ${s.enabled?'':'off'}" data-toggle-layer="${esc(s.id)}" data-kind="${kind}" title="${s.enabled?'Mute':'Unmute'}">${ic(s.enabled?'eye':'eyeoff',15)}</button></div>`).join('')||'<div class="empty-message">No layers yet. Build an original effect or sound above, or use a starter preset.</div>';}
function renderPresets(){const isSound=workspace==='audio',list=workspace==='composer'?[...effectPresets.map(p=>({...p,kind:'emitter'})),...soundPresets.map(p=>({...p,kind:'sound'}))]:isSound?soundPresets.map(p=>({...p,kind:'sound'})):effectPresets.map(p=>({...p,kind:'emitter'})),term=$('preset-search').value.toLowerCase().trim();$('preset-title').textContent=workspace==='composer'?'Effect + sound palette':isSound?'Sound palette':'Effect palette';$('preset-list').innerHTML=list.filter(p=>(p.label+' '+p.category+' '+p.description).toLowerCase().includes(term)).map(p=>`<button class="preset-card" data-add-preset="${p.id}" data-kind="${p.kind}" style="--tone:${p.tone}" title="${esc(p.description)}"><div class="preset-art"><span>${p.icon}</span></div><div><strong>${esc(p.label)}</strong><small>${esc(p.category)} · ${p.kind==='sound'?'Audio':'VFX'}</small></div><span class="plus">＋</span></button>`).join('')||'<div class="empty-message">No matching presets.</div>';}
const limits={start:[0,30,.05],duration:[.05,30,.05],x:[-25,25,.1],y:[-25,25,.1],z:[-25,25,.1],rate:[0,400,1],burst:[0,350,1],life:[.1,12,.05],speed:[0,24,.1],spread:[0,180,1],gravity:[-20,20,.2],drag:[0,6,.05],turbulence:[0,5,.05],sizeStart:[0,3,.02],sizeEnd:[0,3,.02],opacityStart:[0,1,.02],opacityEnd:[0,1,.02],freq:[20,4000,1],endFreq:[20,4000,1],attack:[.001,2,.005],release:[.005,4,.01],volume:[0,1.25,.01],pan:[-1,1,.02],noise:[0,1,.01],filter:[100,18000,50],drive:[0,1,.02],echo:[0,.7,.02]};
const labels={rate:'Emission rate',burst:'Initial burst',life:'Particle lifetime',speed:'Particle velocity',spread:'Directional spread',gravity:'Vertical acceleration',drag:'Air resistance',turbulence:'Turbulence',sizeStart:'Initial size',sizeEnd:'Final size',opacityStart:'Initial opacity',opacityEnd:'Final opacity',freq:'Start frequency',endFreq:'End frequency',attack:'Attack',release:'Release',volume:'Gain',pan:'Stereo pan',noise:'Noise blend',filter:'Low-pass cutoff',drive:'Saturation',echo:'Delay feedback',start:'Start time',duration:'Duration',x:'X position',y:'Y position',z:'Z position'};
const units={rate:'/s',burst:'',life:' s',speed:' st/s',spread:'°',gravity:' st/s²',drag:'',turbulence:'',sizeStart:' st',sizeEnd:' st',opacityStart:'',opacityEnd:'',freq:' Hz',endFreq:' Hz',attack:' s',release:' s',volume:'',pan:'',noise:'',filter:' Hz',drive:'',echo:'',start:' s',duration:' s',x:' st',y:' st',z:' st'};
const showVal=(name,v)=>{const n=Number(v);return (Number.isInteger(n)?String(n):n.toFixed(n<1?2:1))+String(units[name]||'');};
function fld(key){const [min,max,step]=limits[key],s=getSelected(),value=clamp(s?.[key]??0,min,max);return `<div class="field"><div class="field-top"><label for="range-${key}">${labels[key]||key}</label><output id="out-${key}">${showVal(key,value)}</output></div><div class="rangeinput"><input id="range-${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" data-bind="${key}"/><input type="number" min="${min}" max="${max}" step="${step}" value="${value}" data-bind="${key}" title="${labels[key]} numerical value"/></div></div>`;}
function fieldText(key,label,placeholder=''){const s=getSelected();return `<div class="field"><div class="field-top"><label for="field-${key}">${label}</label></div><input id="field-${key}" type="text" data-bind="${key}" value="${esc(s?.[key]??'')}" placeholder="${esc(placeholder)}"/></div>`;}
function sel(key,label,entries){const s=getSelected();return `<div class="field"><div class="field-top"><label for="sel-${key}">${label}</label></div><select id="sel-${key}" data-bind="${key}">${entries.map(([id,name])=>`<option value="${id}" ${s?.[key]===id?'selected':''}>${name}</option>`).join('')}</select></div>`;}
function color(key,label){return `<div class="field"><div class="field-top"><label>${label}</label></div><input type="color" data-bind="${key}" value="${esc(getSelected()?.[key]||'#ffffff')}"/></div>`;}
function check(key,label){return `<label class="checkrow">${label}<input type="checkbox" data-bind="${key}" ${getSelected()?.[key]?'checked':''}/></label>`;}
const group=(name,fields)=>`<section class="group"><div class="group-title">${name}<span>${ic('chevron',11)}</span></div>${fields}</section>`;
function renderInspector(){const s=getSelected();$('inspector-title').textContent=s?selection.kind==='emitter'?'Particle Emitter':'Audio Layer':'Inspector';if(!s){$('inspector').innerHTML=`<div class="inspect-empty">${ic('layers',33)}<strong>Nothing selected</strong><p>Add a preset or select a layer to edit its settings.</p></div>`;return;}
 let html=group('Layer identity',fieldText('name','Name')+check('enabled','Enabled')+check('solo','Solo layer')+fld('start')+fld('duration'));
 if(selection.kind==='emitter'){
 html+=group('Emitter source',sel('shape','Spawn shape',[['point','Point'],['sphere','Sphere'],['disc','Disc'],['ring','Ring'],['box','Volume / box']])+fld('rate')+fld('burst')+fld('life'));
 html+=group('Motion & physics',fld('speed')+fld('spread')+fld('gravity')+fld('drag')+fld('turbulence'));
 html+=group('Particle appearance',sel('sprite','Sprite shape',[['glow','Soft glow'],['spark','Star streak'],['star','Five-point star'],['ring','Ring'],['square','Square'],['smoke','Soft cloud']])+sel('blend','Blend mode',[['add','Additive glow'],['normal','Normal / alpha']])+`<div class="colors">${color('colorStart','Start colour')}${color('colorEnd','End colour')}</div>`+fld('sizeStart')+fld('sizeEnd')+fld('opacityStart')+fld('opacityEnd'));
 html+=group('Emitter position',`<div class="inline-fields three">${['x','y','z'].map(k=>`<div class="field"><div class="field-top"><label>${k.toUpperCase()} / STUDS</label></div><input type="number" min="-25" max="25" step=".1" value="${s[k]}" data-bind="${k}"/></div>`).join('')}</div>`);
 html+=group('Roblox asset',fieldText('textureId','Uploaded sprite asset ID','rbxassetid://123456789')+`<div class="asset-note">Procedural preview sprites are generated locally. Export a sprite PNG, upload it through Roblox Creator Dashboard, then enter the asset ID for matching ParticleEmitter textures.</div><button class="inspector-button" data-action="sprite-png">${ic('download',14)} Export sprite PNG</button>`);
 }else{
 html+=group('Synthesizer',sel('kind','Source',[['tone','Oscillator'],['noise','Noise + tone'],['pluck','Plucked string'],['bell','Metallic bell'],['sample','Imported sample']])+sel('wave','Oscillator waveform',[['sine','Sine'],['triangle','Triangle'],['saw','Sawtooth'],['square','Square']])+fld('freq')+fld('endFreq')+fld('noise'));
 html+=group('Amplitude envelope',fld('attack')+fld('release')+fld('volume')+fld('pan'));
 html+=group('Sound processing',fld('filter')+fld('drive')+fld('echo')+check('reverse','Reverse envelope'));
 html+=group('Roblox audio asset',fieldText('assetId','Uploaded Roblox sound ID','rbxassetid://123456789')+`<div class="asset-note">Export a WAV and upload it through Creator Dashboard, then paste its sound asset ID here. Luau export will schedule the Sound automatically.</div>`);
 html+=group('Output',`<button class="inspector-button" data-action="preview-sound">${ic('play',14)} Preview this sound</button><button class="inspector-button" data-action="export-selected-audio">${ic('download',14)} Export this sound as WAV</button>${s.sample?`<div class="asset-note">Imported sample: ${(s.sample.data.length/s.sample.rate).toFixed(2)} seconds (saved in project file).</div>`:''}`);
 }
 html+=group('Layer actions',`<div class="inspect-actions"><button class="inspector-button" data-action="move-up">↑ Move up</button><button class="inspector-button" data-action="move-down">↓ Move down</button><button class="inspector-button" data-action="duplicate">${ic('duplicate',14)} Duplicate</button><button class="inspector-button danger" data-action="delete">${ic('trash',14)} Delete layer</button></div>`);
 $('inspector').innerHTML=html;
}

function renderStage(){const audio=workspace==='audio';$('particle-space').classList.toggle('hidden',audio);$('audio-space').classList.toggle('hidden',!audio);$('stage-title').textContent=audio?'Sound synthesis preview':workspace==='composer'?'Cue scene preview':'Live particle preview';$('stage-subtitle').textContent=audio?'STEREO AUDIO ENGINE':workspace==='composer'?'SYNCED PARTICLE + AUDIO':'3D PARTICLE VIEW';$('effect-title').textContent=workspace==='composer'?'Scene cue composer':'Particle laboratory';$('effect-description').textContent=workspace==='composer'?'Combine emitter animations and designed audio clips on one timeline.':'Preview each effect in 3D. Adjust its lifetime, colours, motion, density and sprite.';
 $('burst-button').classList.toggle('hidden',audio);$('grid-button').classList.toggle('hidden',audio);$('background-button').classList.toggle('hidden',audio);document.querySelector('[data-action="camera-menu"]').classList.toggle('hidden',audio);document.querySelector('[data-action="reset-view"]').classList.toggle('hidden',audio);
 $('grid-button').classList.toggle('active',project.settings.grid);$('audio-tracks').textContent=project.sounds.filter(s=>s.enabled).length;waveDirty=true;}
const timelineItems=()=>workspace==='vfx'?project.emitters.map(s=>({kind:'emitter',item:s})):workspace==='audio'?project.sounds.map(s=>({kind:'sound',item:s})): [...project.emitters.map(s=>({kind:'emitter',item:s})),...project.sounds.map(s=>({kind:'sound',item:s}))];
function renderTimeline(){const tracks=timelineItems(),duration=project.duration,width=Math.max(duration*timelineScale,650);$('timeline-content').style.width=width+'px';$('ruler').innerHTML=Array.from({length:Math.floor(duration)+1},(_,i)=>`<span class="tick" style="left:${i*timelineScale}px">${i}s</span>`).join('');$('track-labels').innerHTML='<div class="ruler-pad">TRACKS</div>'+tracks.map(({kind,item})=>`<div class="tracklabel ${selection.id===item.id?'selected':''}" data-select="${esc(item.id)}" data-kind="${kind}"><i style="background:${kind==='emitter'?esc(item.colorStart):'#b79dff'}"></i><span>${esc(item.name)}</span></div>`).join('');$('track-lanes').innerHTML=tracks.map(({kind,item})=>{const position=clamp(item.start,0,30),span=Math.max(.05,Math.min(item.duration,30-position)),isSelected=selection.id===item.id,color=kind==='emitter'?item.colorStart:'#ad9aff';return `<div class="tracklane ${isSelected?'selected':''}" data-select="${esc(item.id)}" data-kind="${kind}"><div class="clip ${isSelected?'selected':''}" data-clip="${esc(item.id)}" data-kind="${kind}" style="left:${position*timelineScale}px;width:${Math.max(10,span*timelineScale)}px;--clip:${esc(color)}" title="${esc(item.name)} · Drag to move or resize"><span class="clip-label">${kind==='emitter'?'✦':'♫'} ${esc(item.name)}</span><span class="resize" title="Drag to resize"></span></div></div>`;}).join('');$('timeline-count').textContent=tracks.length+' TRACKS';renderPlayhead();}
function renderPlayhead(){const p=$('playhead');p.style.left=(currentTime*timelineScale)+'px';const min=String(Math.floor(currentTime/60)).padStart(2,'0'),sec=String(Math.floor(currentTime%60)).padStart(2,'0'),cent=String(Math.floor(currentTime%1*100)).padStart(2,'0');$('time-readout').innerHTML=`${min}:${sec}.${cent} <small>/ 00:${String(project.duration).padStart(2,'0')}</small>`;}
function setField(key,value,commit=false){const s=getSelected();if(!s)return;let next=value;
 if(limits[key])next=toNumber(value,limits[key][0],limits[key][1]);else if(['enabled','solo','reverse'].includes(key))next=!!value;else if(key==='name')next=String(value).slice(0,100);else if(key==='textureId'||key==='assetId')next=String(value).slice(0,100);else if(['colorStart','colorEnd'].includes(key)){if(!/^#[\da-fA-F]{6}$/.test(value))return;}else if(!['shape','sprite','blend','kind','wave'].includes(key))return;
 if(key==='duration')next=Math.min(next,Math.max(.05,project.duration-s.start));if(key==='start'){next=Math.min(next,project.duration-.05);s.duration=Math.min(s.duration,project.duration-next);}s[key]=next;
 if(commit){snap('Adjust '+(labels[key]||key));renderAll();}else{const out=$('out-'+key);if(out)out.textContent=showVal(key,next);document.querySelectorAll(`[data-bind="${key}"]`).forEach(input=>{if(input!==document.activeElement&&(input.type==='range'||input.type==='number'))input.value=next;});if(['start','duration','name','enabled','solo','rate','life','colorStart','colorEnd','volume','freq'].includes(key)){renderLibrary();renderTimeline();}waveDirty=true;}
}
function saveProject(){downloadFile(fileBase(project.name)+'.spectra.json',JSON.stringify(project,null,2),'application/json');notify('Project saved as JSON');}
function loadProjectFile(){const input=$('open-file');input.value='';input.click();}
function exportLua(){downloadFile(fileBase(project.name)+'-roblox-vfx.server.lua',exportRobloxLua(project),'text/plain');notify('Roblox Luau emitter setup exported');}
function exportWav(selectedOnly=false){if(selectedOnly&&selection.kind!=='sound')return notify('Select an audio layer first',true);try{const rendered=selectedOnly?renderMix({...project,sounds:project.sounds.map(s=>({...s,enabled:s.id===selection.id,start:0,solo:false}))},AUDIO_RATE):renderMix(project,AUDIO_RATE);downloadFile(fileBase(project.name)+(selectedOnly?'-layer':'-master')+'.wav',new Blob([soundToWav(rendered)],{type:'audio/wav'}));notify(selectedOnly?'Selected sound exported as WAV':'Stereo master exported as WAV');}catch(e){console.error(e);notify('Audio rendering failed: '+e.message,true);}}
function exportSprite(){const s=getSelected();if(!s||selection.kind!=='emitter')return notify('Select a particle layer to export its sprite',true);const c=makeSpritePNG(s.sprite,s.colorStart);c.toBlob(blob=>{if(blob){downloadFile(fileBase(s.name)+'-sprite.png',blob);notify('Sprite exported. Upload the PNG to Roblox for an asset ID.');}},'image/png');}
function exportPreview(){const canvas=workspace==='audio'?$('waveform'):$('stage-canvas');canvas.toBlob(blob=>{if(blob){downloadFile(fileBase(project.name)+'-preview.png',blob);notify('Preview image saved');}},'image/png');}
async function importSoundFile(file){if(!file)return;if(file.size>20e6)return notify('Audio file is larger than the 20 MB import limit',true);try{const context=audioCtx||(audioCtx=new (window.AudioContext||window.webkitAudioContext)());const buffer=await context.decodeAudioData(await file.arrayBuffer());const data=buffer.getChannelData(0);const sample=importSample(data,buffer.sampleRate);const s=createSound('whoosh');s.name=file.name.replace(/\.[^.]+$/,'').slice(0,60);s.kind='sample';s.duration=Math.max(.05,Math.min(12,sample.data.length/sample.rate));s.attack=.002;s.release=.08;s.volume=.8;s.noise=0;s.drive=0;s.echo=0;s.freq=s.endFreq=440;s.sample=sample;s.start=Math.min(currentTime,Math.max(0,project.duration-.05));project.sounds.push(s);selection={kind:'sound',id:s.id};workspace='audio';snap('Import sound '+s.name);renderAll();notify('Imported '+s.name+' · first 12 seconds saved in project');}catch(e){console.error(e);notify('Could not decode audio file',true);}}
function stopAudio(){if(audioNode){try{audioNode.stop();}catch{}try{audioNode.disconnect();}catch{}audioNode=null;}if(soundPreviewNode){try{soundPreviewNode.stop();}catch{}soundPreviewNode=null;}}
async function previewSound(){const s=selection.kind==='sound'?getSelected():project.sounds[0];if(!s)return notify('Add a sound layer first',true);try{if(soundPreviewNode){try{soundPreviewNode.stop();}catch{}}const result=await playBuffer(renderSound(s),audioCtx);audioCtx=result.ctx;soundPreviewNode=result.node;notify('Previewing '+s.name);}catch(e){console.error(e);notify('Audio playback was blocked. Click Play to enable audio.',true);}}
async function togglePlayback(){if(playing){pause();return;}if(currentTime>=project.duration-.01)currentTime=0;stopAudio();playOffset=currentTime;playStarted=performance.now();playing=true;preview.seek(currentTime);$('play-button').innerHTML=ic('pause');$('play-button').title='Pause (Space)';try{const rendered=renderMix(project,AUDIO_RATE);const result=await playBuffer(rendered,audioCtx);audioCtx=result.ctx;audioNode=result.node;if(!playing){stopAudio();return;}playStarted=performance.now();}catch(e){console.warn('Sound playback unavailable',e);notify('Visual playback only — browser audio unavailable',true);}}
function pause(){if(!playing)return;currentTime=Math.min(project.duration,playOffset+(performance.now()-playStarted)/1000);playing=false;stopAudio();$('play-button').innerHTML=ic('play');$('play-button').title='Play (Space)';renderPlayhead();}
function stop(){pause();currentTime=0;preview.reset();renderPlayhead();}
function seek(time){const shouldResume=playing;if(shouldResume)pause();currentTime=clamp(time,0,project.duration);preview.seek(currentTime);renderPlayhead();if(shouldResume)togglePlayback();}
function action(name){switch(name){case 'new':newProject();break;case 'save':saveProject();break;case 'open':loadProjectFile();break;case 'export-lua':exportLua();break;case 'export-wav':exportWav();break;case 'export-selected-audio':exportWav(true);break;case 'sprite-png':exportSprite();break;case 'preview-png':exportPreview();break;case 'import-sound':$('import-sound').value='';$('import-sound').click();break;case 'undo':undo();break;case 'redo':redo();break;case 'duplicate':duplicate();break;case 'delete':remove();break;case 'add-layer':add(workspace==='audio'||(workspace==='composer'&&selection.kind==='sound')?'sound':'emitter','blank');break;case 'blank-vfx':add('emitter','blank');break;case 'blank-audio':add('sound','blank');break;case 'move-up':moveLayer(-1);break;case 'move-down':moveLayer(1);break;case 'play':togglePlayback();break;case 'restart':seek(0);break;case 'stop':stop();break;case 'burst':{const s=selection.kind==='emitter'?getSelected():project.emitters[0];if(s)preview.burst(s.id);else notify('Add an effect layer first',true);break;}case 'grid':project.settings.grid=!project.settings.grid;preview.grid=project.settings.grid;snap('Toggle viewport grid');renderStage();break;case 'background':project.settings.background=project.settings.background==='studio'?'light':'studio';preview.background=project.settings.background;snap('Change preview background');break;case 'view-iso':preview.setView('iso');break;case 'view-top':preview.setView('top');break;case 'view-front':preview.setView('front');break;case 'reset-view':preview.setView('iso');break;case 'zoom-in':timelineScale=clamp(timelineScale+15,45,170);renderTimeline();break;case 'zoom-out':timelineScale=clamp(timelineScale-15,45,170);renderTimeline();break;case 'preview-sound':previewSound();break;case 'help':showHelp();break;case 'roblox-help':showRobloxHelp();break;case 'export-menu':showMenu('export',document.querySelector('[data-action="export-menu"]'));break;case 'camera-menu':showMenu('camera',document.querySelector('[data-action="camera-menu"]'));break;}}
const menuDefinitions={
 file:[['New blank project','new','Ctrl+N'],['Open project…','open','Ctrl+O'],['Save project','save','Ctrl+S'],'-', ['Import audio…','import-sound',''],['Export Roblox Luau','export-lua',''],['Export stereo WAV','export-wav','']],
 edit:[['Undo','undo','Ctrl+Z'],['Redo','redo','Ctrl+Shift+Z'],'-',['Duplicate layer','duplicate','Ctrl+D'],['Delete layer','delete','Del']],
 create:[['Blank particle emitter','blank-vfx',''],['Blank sound synthesizer','blank-audio',''],'-',['Import an audio sample…','import-sound','']],
 view:[['Perspective','view-iso',''],['Top view','view-top',''],['Front view','view-front',''],'-',['Toggle grid','grid',''],['Toggle background','background',''],['Export screenshot','preview-png','']],
 help:[['Keyboard shortcuts','help','?'],['Using assets in Roblox','roblox-help','']],
 camera:[['Perspective','view-iso',''],['Top view','view-top',''],['Front view','view-front','']],
 export:[['Roblox particle script (.lua)','export-lua',''],['Stereo mix (.wav)','export-wav',''],['Selected sound (.wav)','export-selected-audio',''],['Selected particle sprite (.png)','sprite-png',''],['Preview image (.png)','preview-png',''],['Project (.json)','save','']]
};
let openMenuName=null;
function closeMenu(){$('dropdown').classList.add('hidden');openMenuName=null;document.querySelectorAll('[data-menu]').forEach(b=>b.classList.remove('active'));}
function showMenu(name,anchor){if(openMenuName===name){closeMenu();return;}const pop=$('dropdown'),items=menuDefinitions[name]||[];pop.innerHTML=items.map(item=>item==='-'?'<div class="sep"></div>':`<button data-action="${item[1]}"><span>${esc(item[0])}</span><kbd>${esc(item[2]||'')}</kbd></button>`).join('');pop.classList.remove('hidden');const rect=anchor?.getBoundingClientRect()||{left:10,bottom:60,right:80};const width=228;pop.style.left=Math.max(10,Math.min(window.innerWidth-width-10,rect.left))+'px';pop.style.top=rect.bottom+5+'px';openMenuName=name;document.querySelectorAll('[data-menu]').forEach(b=>b.classList.toggle('active',b.dataset.menu===name));}
function showModal(title,body){$('modal').innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${esc(title)}</h2><button data-action="modal-close" aria-label="Close dialog">×</button></div><div class="modal-content">${body}</div></div>`;$('modal').classList.remove('hidden');}
function showHelp(){showModal('Spectra keyboard shortcuts',`<p>Every menu item shown here has a working action. Spectra saves an autosave in this browser, and you can download portable project files from <b>File → Save</b>.</p><div class="shortcut-grid">${[['Play / pause','Space'],['Stop','Esc'],['Save project','Ctrl+S'],['Open project','Ctrl+O'],['New project','Ctrl+N'],['Undo','Ctrl+Z'],['Redo','Ctrl+Shift+Z'],['Duplicate layer','Ctrl+D'],['Delete layer','Delete'],['Orbit stage','Right-drag'],['Pan stage','Middle-drag'],['Zoom stage','Scroll'],['Timeline beat snapping','Shift+drag']].map(([a,b])=>`<div class="shortcut"><span>${a}</span><kbd>${b}</kbd></div>`).join('')}</div><h3>How to create an effect</h3><p>Go to <b>Particle Lab</b>, click <b>New Effect</b>, then edit colour, shape, velocity and lifetime in the Inspector. Presets are optional starting points. Use Emit burst to preview it; drag the timeline clip to schedule it.</p><h3>How to create a sound</h3><p>Go to <b>Sound Studio</b>, click <b>New Sound</b> for a blank synthesizer or import your own sample; edit frequency, envelope, filter and effects. Play the mix and export a WAV.</p>`);}
function showRobloxHelp(){showModal('Using Spectra assets in Roblox',`<h3>1. Particle effects</h3><p>Export <b>Roblox particle script (.lua)</b>. Paste the Luau into a Script in Roblox Studio. The script creates a temporary anchored Part with Attachments and configured ParticleEmitters. You can move that attachment setup into your game systems.</p><h3>2. Textures and sprites</h3><p>Roblox ParticleEmitter textures must reference Roblox assets. Select an emitter and export its sprite PNG, then upload that PNG using the Roblox Creator Dashboard. Paste the approved asset ID into the emitter's <b>Uploaded sprite asset ID</b> field, then re-export the script.</p><h3>3. Audio</h3><p>Export your designed sounds as stereo WAV files and upload them to Roblox. Roblox gives you audio asset IDs, which you can use with Sound objects. A browser app cannot assign Roblox asset IDs directly.</p><p><b>Preview differences:</b> This is a browser-based particle simulation. Roblox particle rendering, blending and audio spatialization may differ. Validate final effects in Roblox Studio.</p><p><a href="https://create.roblox.com/docs/reference/engine/classes/ParticleEmitter" target="_blank" rel="noopener">Roblox particle documentation</a> · <a href="https://create.roblox.com/docs/sound/objects" target="_blank" rel="noopener">Roblox sound documentation</a></p>`);}
let waveBins=null;
function drawWaveform(){if(workspace!=='audio')return;const canvas=$('waveform'),rect=canvas.getBoundingClientRect();if(rect.width<1||rect.height<1)return;const dpr=Math.min(devicePixelRatio||1,2),width=Math.max(1,Math.round(rect.width*dpr)),height=Math.max(1,Math.round(rect.height*dpr));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;waveDirty=true;}
 if(waveDirty||!waveBins){const mix=renderMix(project,11025),steps=Math.min(900,Math.max(300,Math.round(width/2))),binsL=[],binsR=[],length=Math.min(mix.left.length,Math.floor(project.duration*11025));for(let j=0;j<steps;j++){const from=Math.floor(j/steps*length),to=Math.max(from+1,Math.floor((j+1)/steps*length)),stride=Math.max(1,Math.floor((to-from)/20));let peakL=0,peakR=0;for(let k=from;k<to;k+=stride){peakL=Math.max(peakL,Math.abs(mix.left[k]||0));peakR=Math.max(peakR,Math.abs(mix.right[k]||0));}binsL.push(peakL);binsR.push(peakR);}waveBins={left:binsL,right:binsR};waveDirty=false;$('wave-info').textContent='Stereo master · '+project.sounds.filter(s=>s.enabled).length+' active layers · WAV-ready';}
 const ctx=canvas.getContext('2d');ctx.clearRect(0,0,width,height);const half=height/2;const colors=['#7fc8ee','#ae9af6'];const channels=[waveBins.left,waveBins.right];ctx.fillStyle='#151e2b77';ctx.fillRect(0,0,width,height);
 for(let ch=0;ch<2;ch++){const points=channels[ch],count=points.length,center=height*(ch===0?.26:.75),amp=height*.22;ctx.strokeStyle=colors[ch]+'bb';ctx.lineWidth=Math.max(1,dpr);ctx.beginPath();ctx.moveTo(0,center);ctx.lineTo(width,center);ctx.stroke();const grad=ctx.createLinearGradient(0,center-amp,0,center+amp);grad.addColorStop(0,colors[ch]+'da');grad.addColorStop(.5,colors[ch]+'50');grad.addColorStop(1,colors[ch]+'da');ctx.fillStyle=grad;ctx.beginPath();for(let i=0;i<count;i++){const x=i/(count-1)*width,y=center-points[i]*amp;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}for(let i=count-1;i>=0;i--){ctx.lineTo(i/(count-1)*width,center+points[i]*amp);}ctx.closePath();ctx.fill();}
 const cursor=currentTime/project.duration*width;ctx.strokeStyle='#f3c0a3';ctx.lineWidth=2*dpr;ctx.beginPath();ctx.moveTo(cursor,0);ctx.lineTo(cursor,height);ctx.stroke();ctx.fillStyle='#f3c0a3';ctx.fillRect(cursor-4*dpr,0,8*dpr,4*dpr);
}
function handleTimelineDown(e){const clip=e.target.closest('[data-clip]');if(!clip||e.button!==0)return;e.preventDefault();const id=clip.dataset.clip,kind=clip.dataset.kind,layer=listFor(kind).find(s=>s.id===id);if(!layer)return;selection={kind,id};const resize=!!e.target.closest('.resize');timelineDrag={id,kind,clip,startX:e.clientX,start:layer.start,duration:layer.duration,resize,moved:false,pointerId:e.pointerId};clip.setPointerCapture(e.pointerId);document.querySelectorAll('.clip,.tracklabel').forEach(b=>b.classList.toggle('selected',b.dataset.clip===id||b.dataset.select===id));renderLibrary();renderInspector();}
function handleTimelineMove(e){const d=timelineDrag;if(!d)return;const layer=listFor(d.kind).find(x=>x.id===d.id);if(!layer)return;const change=(e.clientX-d.startX)/timelineScale;let target=d.resize?d.duration+change:d.start+change;const step=e.shiftKey?60/project.bpm:.05;target=Math.round(target/step)*step;if(d.resize){layer.duration=clamp(target,.05,project.duration-layer.start);d.clip.style.width=Math.max(10,layer.duration*timelineScale)+'px';}else{layer.start=clamp(target,0,project.duration-layer.duration);d.clip.style.left=layer.start*timelineScale+'px';}d.moved=d.moved||Math.abs(e.clientX-d.startX)>2;}
function handleTimelineUp(){if(!timelineDrag)return;const moved=timelineDrag.moved;timelineDrag=null;if(moved)snap('Move or resize timeline clip');renderAll();}
$('timeline-content').addEventListener('pointerdown',handleTimelineDown);$('timeline-content').addEventListener('pointermove',handleTimelineMove);$('timeline-content').addEventListener('pointerup',handleTimelineUp);$('timeline-content').addEventListener('pointercancel',handleTimelineUp);
$('ruler').addEventListener('pointerdown',e=>{if(e.button!==0)return;const rect=$('ruler').getBoundingClientRect();seek((e.clientX-rect.left)/timelineScale);});
$('timeline-scroll').addEventListener('scroll',()=>{$('track-labels').scrollTop=$('timeline-scroll').scrollTop;});
$('waveform').addEventListener('pointerdown',e=>{if(e.button!==0)return;const rect=e.currentTarget.getBoundingClientRect();seek((e.clientX-rect.left)/rect.width*project.duration);});
$('stage-canvas').addEventListener('click',e=>{if(e.button!==0)return;if(e.detail!==2)return;const s=selection.kind==='emitter'?getSelected():project.emitters[0];if(s)preview.burst(s.id);});
$('layer-search').addEventListener('input',renderLibrary);$('preset-search').addEventListener('input',renderPresets);
$('project-name').addEventListener('change',e=>{project.name=(e.target.value.trim()||'Untitled Project').slice(0,100);snap('Rename project');renderHeader();});
$('project-duration').addEventListener('change',e=>{project.duration=clamp(e.target.value,1,30);for(const item of [...project.sounds,...project.emitters]){item.start=clamp(item.start,0,project.duration-.05);item.duration=Math.min(item.duration,Math.max(.05,project.duration-item.start));}currentTime=Math.min(project.duration,currentTime);snap('Change project length');renderAll();});
$('project-bpm').addEventListener('change',e=>{project.bpm=clamp(e.target.value,40,240);snap('Change tempo');renderHeader();});
$('open-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>15e6){notify('Project file exceeds the 15 MB limit',true);return;}try{const loaded=validateProject(JSON.parse(await file.text()));stop();project=loaded;workspace='vfx';selection={kind:'emitter',id:project.emitters[0]?.id||null};history=[];historyIndex=-1;snap('Open project');renderAll();notify('Opened '+project.name);}catch(err){notify('Could not open project: '+err.message,true);}e.target.value='';});
$('import-sound').addEventListener('change',async e=>{const file=e.target.files?.[0];await importSoundFile(file);e.target.value='';});
$('inspector').addEventListener('input',e=>{const element=e.target.closest('[data-bind]');if(!element)return;if(element.type==='checkbox'||element.tagName==='SELECT'||element.type==='text')return;setField(element.dataset.bind,element.value,false);});
$('inspector').addEventListener('change',e=>{const element=e.target.closest('[data-bind]');if(!element)return;const key=element.dataset.bind;const val=element.type==='checkbox'?element.checked:element.value;const scroll=$('inspector').scrollTop;setField(key,val,true);$('inspector').scrollTop=scroll;});
document.addEventListener('click',e=>{
 const menuButton=e.target.closest('[data-menu]');if(menuButton){showMenu(menuButton.dataset.menu,menuButton);return;}
 const button=e.target.closest('[data-action]');if(button){const name=button.dataset.action;if(name==='modal-close'){$('modal').classList.add('hidden');return;}closeMenu();action(name);return;}
 const workspaceButton=e.target.closest('[data-workspace]');if(workspaceButton){closeMenu();setWorkspace(workspaceButton.dataset.workspace);return;}
 const presetButton=e.target.closest('[data-add-preset]');if(presetButton){add(presetButton.dataset.kind,presetButton.dataset.addPreset);return;}
 const visibility=e.target.closest('[data-toggle-layer]');if(visibility){toggleLayer(visibility.dataset.kind,visibility.dataset.toggleLayer,'enabled');return;}
 const layer=e.target.closest('[data-select]');if(layer){choose(layer.dataset.kind,layer.dataset.select);return;}
 if(!e.target.closest('.dropdown'))closeMenu();
});
$('modal').addEventListener('click',e=>{if(e.target===$('modal'))$('modal').classList.add('hidden');});
document.addEventListener('keydown',e=>{
 const target=e.target;if(['INPUT','TEXTAREA','SELECT'].includes(target?.tagName)||target?.isContentEditable)return;
 const ctrl=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();
 if(ctrl&&key==='s'){e.preventDefault();saveProject();return;}
 if(ctrl&&key==='o'){e.preventDefault();loadProjectFile();return;}
 if(ctrl&&key==='n'){e.preventDefault();newProject();return;}
 if(ctrl&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}
 if(ctrl&&key==='y'){e.preventDefault();redo();return;}
 if(ctrl&&key==='d'){e.preventDefault();duplicate();return;}
 if(e.key===' '){e.preventDefault();togglePlayback();return;}
 if(e.key==='Escape'){if(!$('modal').classList.contains('hidden'))$('modal').classList.add('hidden');else if(openMenuName)closeMenu();else stop();return;}
 if(e.key==='Delete'||e.key==='Backspace'){remove();return;}
 if(e.key==='?'){showHelp();return;}
});
let wavFrame=0;
function frame(now){let dt=clamp((now-rafLast)/1000,0,.07);rafLast=now;
 if(playing){currentTime=playOffset+(now-playStarted)/1000;if(currentTime>=project.duration){stop();}else renderPlayhead();}
 if(workspace!=='audio'){preview.tick(currentTime,dt,playing);if(now-frameStamp>1000){const fps=Math.round(frameCounter*1000/(now-frameStamp));$('particle-stats').innerHTML=preview.particles.length+' PARTICLES<br/>'+fps+' FPS';frameCounter=0;frameStamp=now;}frameCounter++;}
 else{if(++wavFrame%2===0||waveDirty)drawWaveform();}
 requestAnimationFrame(frame);
}
initSpectraCore({
 getProject:()=>structuredClone(project),
 getSelection:()=>({...selection}),
 applyProject:(draft,changes)=>{
   const validated=validateProject(draft);
   stop();preview.reset();project=validated;
   const created=[...changes].reverse().find(change=>change.type==='add');
   if(created){
     selection={kind:created.kind,id:created.id};
     const addedKinds=new Set(changes.filter(change=>change.type==='add').map(change=>change.kind));
     workspace=addedKinds.size>1?'composer':created.kind==='sound'?'audio':'vfx';
   }
   else if(!getSelected()){selection={kind:'emitter',id:project.emitters[0]?.id||null};}
   snap('Apply Spectra Core changes');
   renderAll();
   if(selection.kind==='emitter'&&getSelected())preview.burst(selection.id);
 },
 notify
});
snap('Initial scene');renderAll();preview.draw();if(project.emitters[0]){preview.burst(project.emitters[0].id,70);if(project.emitters[1])preview.burst(project.emitters[1].id,45);}requestAnimationFrame(frame);
window.addEventListener('error',e=>{console.error('Spectra runtime error',e.error||e.message);notify('Editor error: '+e.message,true);});